import type { SignatureErrorType } from '~/client';
import type { AlertVariants } from '~/components/ui/alert';
import { CircleAlertIcon } from 'lucide-vue-next';

export const submittedSignaturesErrors: Record<
  SignatureErrorType,
  {
    label: string;
    icon: Component;
    variant: AlertVariants['variant'];
    title: string;
    description: string;
  }
> = {
  voter_not_found: {
    variant: 'destructive',
    icon: CircleAlertIcon,
    label: 'Voter Was Not Found',
    title: 'Voter was not found',
    description: 'Voter was not found in the voter database',
  },
  incomplete_form: {
    variant: 'destructive',
    icon: CircleAlertIcon,
    label: 'Incomplete Form',
    title: 'Incomplete form submitted',
    description: 'Key fields are lacking in submitted signature',
  },
  internal: {
    variant: 'destructive',
    icon: CircleAlertIcon,
    label: 'Internal',
    title: 'Internal Error',
    description: 'Encountered internal server error during processing',
  },
  missing_signed_date: {
    variant: 'destructive',
    icon: CircleAlertIcon,
    label: 'Missing Signed Date',
    title: 'Missing signed date',
    description: 'Signature is missing the signing date',
  },
  invalid_signed_date: {
    variant: 'destructive',
    icon: CircleAlertIcon,
    label: 'Invalid Signed Date',
    title: 'Invalid signed date',
    description: 'Signature signed date is outside of the project date range',
  },
};

const defaultSubmittedSignatureError: {
  label: string;
  icon: Component;
  variant: AlertVariants['variant'];
  title: string;
  description: string;
} = {
  label: '',
  icon: CircleAlertIcon,
  variant: 'destructive',
  title: 'Error',
  description: '',
};

export function getSubmittedSignatureError(error: SignatureErrorType): {
  label: string;
  icon: Component;
  variant: AlertVariants['variant'];
  title: string;
  description: string;
} {
  return (
    submittedSignaturesErrors[error] ?? {
      ...defaultSubmittedSignatureError,
      label: snakeCaseToCapitalizedCase(error),
      title: snakeCaseToCapitalizedCase(error),
    }
  );
}

export const submittedSignaturesErrorsOptions: SelectItem<SignatureErrorType>[] = Object.entries(
  submittedSignaturesErrors
).map(([value, { label }]) => ({
  value: value as SignatureErrorType,
  name: label,
}));
